console.log('克隆已有数据库:', data);
if (data && data.id) {
    const serviceUtil = ibiz.hub.getApp(context.srfappid).deService;
    const kbService = await serviceUtil.getService(context, 'plmweb.ai_knowledge_base');
    const kbTempData = await kbService.local.get(context, data.id);
    console.log('临时数据为:', kbTempData);
    var copy_target = data.copy_target;
    if (data.use_copy === 1 && copy_target !== null) {
        // 创建独立上下文（避免污染全局context）
        const copyContext = {
            ...context,
            ai_knowledge_base: copy_target
        };
        const res = await kbService.get(copyContext)
        if (res && res.ok) {
            var targetData = res.data;
            console.log('克隆已有数据库:', targetData);
            data.parser_config = targetData.parser_config
        }
    }
}
return data;
